(function(){'use strict';
  const UI_KEY='informatikPortal_ui_v1';
  const page=(location.pathname.split('/').pop()||'').toLowerCase();
  const map=page.includes('onenote')?{id:'onenote',name:'OneNote',area:'Grundlagen',nav:'grundlagen',week:''}:page.includes('scannen')?{id:'scan',name:'Scannen mit OneDrive',area:'Woche 38',nav:'wochen',week:'38'}:{id:'digipen',name:'DigiPen',area:'Woche 38',nav:'wochen',week:'38'};
  const read=()=>{try{return JSON.parse(localStorage.getItem(UI_KEY)||'{}')}catch{return {}}};
  const save=p=>{try{localStorage.setItem(UI_KEY,JSON.stringify({...read(),...p,version:1,updatedAt:new Date().toISOString()}))}catch{}};
  const links=[['start','Start'],['wochen','Wochen'],['grundlagen','Grundlagen'],['training','Training'],['fortschritt','Fortschritt']];
  function markup(){const nav=links.map(([id,label])=>`<a href="index.html#${id}" ${id===map.nav?'aria-current="page"':''}>${label}</a>`).join('');return `<a class="portal-shell-skip" href="#workshop-main">Zum Inhalt springen</a><header class="portal-shell-header"><div class="portal-shell-inner"><a class="portal-shell-brand" href="index.html#start"><span class="portal-shell-mark">IT</span><span>Informatik<small>Digitales Werkstattbuch</small></span></a><nav class="portal-shell-nav" aria-label="Hauptnavigation">${nav}</nav><details class="portal-shell-menu"><summary>Menü</summary><div>${nav}</div></details><button class="portal-shell-font" type="button" data-portal-font aria-pressed="false" title="Schrift deutlich vergrössern">A+</button></div></header>`}
  function routeKey(){return location.pathname+location.hash}
  function taskNumber(){const m=location.hash.match(/auftrag-(\d+)/);return m?Number(m[1]):null}
  function updateContext(){let el=document.querySelector('.portal-context');if(!el){el=document.createElement('div');el.className='portal-context';document.querySelector('.topbar')?.insertAdjacentElement('afterend',el)}const task=taskNumber();el.innerHTML=`<a href="index.html#start">Informatik</a><span>›</span><a href="index.html#${map.nav}">${map.area}</a><span>›</span><a href="#uebersicht">${map.name}</a>${task?`<span>›</span>Auftrag ${task}`:''}`}
  function setLarge(on){document.documentElement.classList.toggle('portal-large',on);document.querySelectorAll('[data-portal-font]').forEach(b=>{b.textContent=on?'A−':'A+';b.setAttribute('aria-pressed',String(on));b.title=on?'Normale Schrift verwenden':'Schrift deutlich vergrössern'});save({largeText:on})}
  function findOriginal(direction,taskSection){if(map.id==='onenote')return taskSection?.querySelector(direction==='prev'?'.task-footer [data-prev],.task-footer [data-go-overview]':'.task-footer [data-next],.task-footer [data-go-overview]');const n=taskNumber();if(direction==='prev'&&n===1)return document.querySelector('#back');if(direction==='next'&&n===7)return document.querySelector('#back');return document.querySelector(direction==='prev'?'#prev':'#next')}
  function addQuickNav(){
    if(map.id==='onenote')document.querySelectorAll('.task-screen .task-card').forEach(card=>{if(card.querySelector(':scope > .portal-quick-nav'))return;const nav=document.createElement('div');nav.className='portal-quick-nav';nav.innerHTML='<button type="button" data-quick="prev">← Vorherige Aufgabe</button><button type="button" data-quick="next">Nächste Aufgabe →</button>';card.querySelector('.task-banner')?.insertAdjacentElement('afterend',nav);nav.addEventListener('click',e=>{const b=e.target.closest('[data-quick]');if(b)findOriginal(b.dataset.quick,card.closest('.task-screen'))?.click()})});
    else{const head=document.querySelector('#taskScreen .taskhead');if(head&&!document.querySelector('#taskScreen .portal-quick-nav')){const nav=document.createElement('div');nav.className='portal-quick-nav';nav.innerHTML='<button type="button" data-quick="prev">← Vorherige Aufgabe</button><button type="button" data-quick="next">Nächste Aufgabe →</button>';head.insertAdjacentElement('afterend',nav);nav.addEventListener('click',e=>{const b=e.target.closest('[data-quick]');if(b)findOriginal(b.dataset.quick)?.click()})}}
    syncQuickNav();
  }
  function syncQuickNav(){const n=taskNumber();document.querySelectorAll('.portal-quick-nav').forEach(nav=>{const section=nav.closest('.task-screen');const active=map.id!=='onenote'||Number(section?.dataset.task)===n;nav.hidden=!active;if(active){const prev=nav.querySelector('[data-quick="prev"]'),next=nav.querySelector('[data-quick="next"]');const op=findOriginal('prev',section),on=findOriginal('next',section);prev.disabled=!op||op.disabled;next.disabled=!on||on.disabled;prev.textContent=n===1?'← Zur Übersicht':'← Vorherige Aufgabe';next.textContent=(map.id==='onenote'&&n===12)||(map.id!=='onenote'&&n===7)?'Zur Übersicht →':'Nächste Aufgabe →'}})}
  function rememberFocus(){const el=document.activeElement;if(!el||!['INPUT','TEXTAREA','SELECT','BUTTON'].includes(el.tagName))return;const id=el.id||el.getAttribute('data-note')||el.getAttribute('data-check');if(!id)return;const data={id,tag:el.tagName,start:typeof el.selectionStart==='number'?el.selectionStart:null,end:typeof el.selectionEnd==='number'?el.selectionEnd:null};sessionStorage.setItem('portalFocus:'+routeKey(),JSON.stringify(data))}
  function restore(){const y=Number(sessionStorage.getItem('portalScroll:'+routeKey())||0);requestAnimationFrame(()=>scrollTo(0,y));try{const f=JSON.parse(sessionStorage.getItem('portalFocus:'+routeKey())||'null');if(f){const esc=window.CSS?.escape?CSS.escape(String(f.id)):String(f.id).replace(/[^a-zA-Z0-9_-]/g,'\\$&');const el=document.getElementById(f.id)||document.querySelector(`[data-note="${esc}"],[data-check="${esc}"]`);if(el){el.focus({preventScroll:true});if(f.start!==null&&el.setSelectionRange)el.setSelectionRange(f.start,f.end)}}}catch{}}
  function routeChanged(){updateContext();syncQuickNav();save({lastModule:map.id,lastRoute:page+location.hash});setTimeout(restore,30)}
  function makeFileLabelsKeyboardFriendly(){document.querySelectorAll('label[for]').forEach(label=>{const input=document.getElementById(label.htmlFor);if(input?.type!=='file')return;label.tabIndex=0;label.setAttribute('role','button');label.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();input.click()}})})}
  document.addEventListener('DOMContentLoaded',()=>{const main=document.querySelector('main');if(main&&!main.id)main.id='workshop-main';document.body.insertAdjacentHTML('afterbegin',markup());setLarge(Boolean(read().largeText));updateContext();addQuickNav();makeFileLabelsKeyboardFriendly();save({lastModule:map.id,lastRoute:page+location.hash});document.querySelectorAll('[data-portal-font]').forEach(b=>b.addEventListener('click',()=>setLarge(!document.documentElement.classList.contains('portal-large'))));document.querySelectorAll('.portal-shell-menu a').forEach(a=>a.addEventListener('click',()=>document.querySelector('.portal-shell-menu').open=false));setTimeout(restore,50)});
  window.addEventListener('hashchange',routeChanged);window.addEventListener('pagehide',rememberFocus);document.addEventListener('focusin',rememberFocus);document.addEventListener('keyup',rememberFocus);window.addEventListener('scroll',()=>{clearTimeout(window.__workshopScroll);window.__workshopScroll=setTimeout(()=>sessionStorage.setItem('portalScroll:'+routeKey(),String(scrollY)),100)},{passive:true});
})();
